function Metric({label,value,detail,icon}:{label:string;value:string;detail:string;icon:React.ReactNode}){return <article className="metric"><div><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><p>{detail}</p></article>;}
function Empty({icon,title,text,action,compact=false}:{icon:React.ReactNode;title:string;text:string;action?:React.ReactNode;compact?:boolean}){return <div className={'empty '+(compact?'compact':'')}><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{text}</p>{action}</div>;}

function MatchDetail({match:m,onClose,portfolio,bets,busy,onSave,onSystem}:{match:Match;onClose:()=>void;portfolio:Portfolio;bets:Bet[];busy:boolean;onSave:(s:Record<string,unknown>)=>void;onSystem:(s:Selection)=>void}){
  const a=analyzeMatch(m);
  const [tab,setTab]=useState('markets'),[countFamily,setCountFamily]=useState('corners'),[countSide,setCountSide]=useState('total'),[market,setMarket]=useState('home'),[odds,setOdds]=useState(m.odds.home?String(m.odds.home):''),[stake,setStake]=useState(String(Math.floor(portfolioMetrics(portfolio,bets).equity*portfolio.stakeBps/10000)/100));
  const p=a?.markets[market]||0,o=Number(odds),validOdds=Number.isFinite(o)&&o>=1.01&&o<=1000,risk=riskCheck(portfolio,bets,Math.round(Number(stake)*100));
  const select=(key:string)=>{setMarket(key);setOdds(m.odds[key]?String(m.odds[key]):'');};
  const [customHome,setCustomHome]=useState('0'),[customAway,setCustomAway]=useState('0');
  const covered=a?a.scores.slice(0,3).reduce((s,v)=>s+v.p,0):0;
  return <Dialog title="Centro partita" onClose={onClose} wide><div className="detail-top"><div><Tag tone={m.source==='demo'?'amber':'green'}>{m.source==='demo'?'SCENARIO SINTETICO':'DATI REALI · PRE-MATCH'}</Tag><p>{m.competition} · {m.source==='demo'?m.kickoff:new Date(m.kickoff).toLocaleString('it-IT',{timeZone:'Europe/Rome'})}</p></div><Tag tone="neutral">MODELLO v2.1 · BACKTEST</Tag></div><div className="detail-teams"><span><Club code={m.homeCode} color={m.homeColor}/><strong>{m.home}</strong></span><div>vs<small>90 MINUTI</small></div><span><Club code={m.awayCode} color={m.awayColor}/><strong>{m.away}</strong></span></div>{!a?<Empty icon={<Info/>} title="Dati insufficienti per una stima." text={m.notes.join(' ')}/>:<><div className="detail-tabs">{[['markets','Mercati'],['exact','Risultati esatti'],['counts','Corner e cartellini'],['model','Logica del modello'],['ai','Analista AI']].filter(([id])=>id!=='ai'||IS_ADMIN).map(([id,label])=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{label}</button>)}</div><div className="detail-columns"><section className="detail-main"><a className="quote-shortcut" href="/quote">Consulta le quote dei bookmaker</a>{tab==='markets'&&<><h3>Come si distribuiscono gli esiti</h3><p className="muted">Probabilità del modello QUORUM v2.1 (rating di squadra, forma, campo, calibrazione da backtest).</p><div className="outcome-bar"><span style={{width:a.markets.home*100+'%'}}/><span style={{width:a.markets.draw*100+'%'}}/><span style={{width:a.markets.away*100+'%'}}/></div><div className="market-list">{['home','draw','away','homeDraw','drawAway','homeAway','over15','under15','over25','under25','over35','under35','btts','noGoal'].map(key=><button className={market===key?'selected':''} key={key} onClick={()=>select(key)}><span>{marketLabel(key)}</span><strong>{percent(a.markets[key])}</strong><small>Equa {(1/a.markets[key]).toFixed(a.markets[key]>.98?3:2)}</small><ChevronRight size={14}/></button>)}</div><p className="footnote">“Quota equa” = 1 ÷ probabilità stimata. Non include il margine del bookmaker e non prova che la stima sia corretta.</p></>}
  {tab==='exact'&&<><h3>I punteggi più probabili</h3><p className="muted">Un risultato esatto resta un evento a probabilità contenuta.</p><div className="exact-grid">{a.scores.slice(0,9).map(s=><button className={market==='exact:'+s.home+'-'+s.away?'selected':''} key={s.home+'-'+s.away} onClick={()=>select('exact:'+s.home+'-'+s.away)}><strong>{s.home} – {s.away}</strong><span>{percent(s.p)}</span><small>Equa {(1/s.p).toFixed(2)}</small></button>)}</div><div className="custom-score"><span>Un altro risultato</span><input aria-label="Gol casa per risultato esatto" type="number" min="0" max="12" step="1" value={customHome} onChange={e=>setCustomHome(e.target.value)}/><span>–</span><input aria-label="Gol ospiti per risultato esatto" type="number" min="0" max="12" step="1" value={customAway} onChange={e=>setCustomAway(e.target.value)}/><button className="secondary" disabled={![customHome,customAway].every(v=>v!==''&&Number.isInteger(Number(v))&&Number(v)>=0&&Number(v)<=12)} onClick={()=>select('exact:'+Number(customHome)+'-'+Number(customAway))}>Analizza</button></div><div className="callout"><Info size={18}/><p>I primi 3 punteggi coprono insieme <strong>{percent(covered)}</strong> degli esiti del modello. Coprirli richiede 3 puntate: una vincita potrebbe non recuperare la spesa complessiva.</p></div></>}
  {tab==='counts'&&<><h3>Corner, cartellini e gol per squadra</h3><p className="muted">Medie di squadra pesate sugli avversari (dati Sportmonks degli ultimi 13 mesi circa).</p><div className="count-filters"><select aria-label="Tipo di evento" value={countFamily} onChange={e=>setCountFamily(e.target.value)}><option value="corners">Calci d’angolo</option><option value="yellow">Cartellini gialli</option><option value="red">Cartellini rossi</option><option value="teamGoals">Gol · totali e squadre</option></select><select aria-label="Squadra o totale" value={countSide} onChange={e=>setCountSide(e.target.value)}><option value="total">Totale partita</option><option value="home">Squadra di casa</option><option value="away">Squadra ospite</option></select></div>{(countFamily==='teamGoals'||m.counts)?<div className="market-list">{Object.keys(a.markets).filter(key=>key.startsWith(countFamily+':'+countSide+':')).map(key=><button className={market===key?'selected':''} key={key} onClick={()=>select(key)}><span>{marketLabel(key)}</span><strong>{percent(a.markets[key])}</strong><small>Equa {a.markets[key]>0?(1/a.markets[key]).toFixed(a.markets[key]>.98?3:2):'—'}</small><ChevronRight size={14}/></button>)}</div>:<div className="callout"><Info size={18}/><p>Statistiche sufficienti non disponibili: nessuna probabilità viene inventata. Il modello reale per questo mercato deve essere addestrato e validato separatamente.</p></div>}<p className="footnote">I rossi sono eventi rari: una probabilità bassa non rende sicuro l’Under. Per i cartellini vanno verificate le regole su doppia ammonizione, panchina e fine partita.</p></>}{tab==='ai'&&IS_ADMIN&&<AiExplanation key={market+odds} match={m} market={market} odds={validOdds?o:null}/>} {tab==='model'&&<><h3>La matematica dietro la stima</h3><div className="lambda-row"><span>Intensità gol casa<strong>{m.lambdaHome?.toFixed(2)}</strong></span><span>Intensità gol ospite<strong>{m.lambdaAway?.toFixed(2)}</strong></span></div><p className="formula">P(H = h, A = a) = Poisson(h; λH) × Poisson(a; λA)</p><p className="muted">La distribuzione combina due conteggi di gol indipendenti. Dai punteggi ricaviamo 1X2, totali gol, Goal/No Goal e doppie chance.</p><ul className="model-notes">{m.notes.map((n,i)=><li key={i}>{n}</li>)}<li>Le intensità gol sono parametri del modello, non valori xG osservati.</li><li>Non applica ancora correzioni Dixon–Coles, Elo o calibrazione. L’indipendenza è un’ipotesi da verificare.</li><li>Queste formule appartengono al modello statistico. L’analista AI, se collegato, le interpreta nella scheda dedicata senza sostituirle.</li></ul></>}
  </section><aside className="selection-panel"><span className="eyebrow">LA TUA IPOTESI</span><h3>{marketLabel(market)}</h3><div className="selection-prob"><strong>{percent(p)}</strong><span>probabilità stimata</span></div><label>Quota {m.source==='demo'?'dimostrativa / modificabile':'verificata da te'}<input type="number" step="0.01" min="1.01" max="1000" value={odds} onChange={e=>setOdds(e.target.value)} placeholder="Inserisci la quota"/></label><div className="selection-math"><span>Quota equa<strong>{(1/p).toFixed(p>.98?3:2)}</strong></span><span>Valore atteso teorico<strong className={validOdds&&p*o-1>0?'positive':''}>{validOdds?percent(p*o-1):'—'}</strong></span></div><p className="tiny">Il valore atteso dipende dall’esattezza della probabilità. Non è un guadagno previsto o garantito.</p><button className="secondary" disabled={!validOdds} onClick={()=>onSystem({fixtureId:m.id,fixture:m.home+' – '+m.away,market,label:marketLabel(market),p,odds:o,competition:m.competition,kickoff:m.kickoff})}><Plus size={15}/>Confronta nel laboratorio</button><div className="selection-divider"/><label>Puntata virtuale (€)<input type="number" step="0.01" min="0.01" value={stake} onChange={e=>setStake(e.target.value)}/></label><small>Limite singolo {money(risk.singleCap)} · {portfolio.name}</small>{risk.reasons.length>0&&<p className="risk-error">{risk.reasons[0]}</p>}<button className="primary" disabled={busy||!validOdds||!risk.allowed} onClick={()=>onSave({fixtureId:m.id,market,odds:o,stakeCents:Math.round(Number(stake)*100)})}>Registra simulazione<ArrowRight size={15}/></button><span className="tiny">Solo diario virtuale. Nessuna scommessa viene inviata.</span></aside></div></>}</Dialog>;
}

function Limits({portfolio:p,metrics:m,busy,onSave,onAction}:{portfolio:Portfolio;metrics:ReturnType<typeof portfolioMetrics>;busy:boolean;onSave:(s:Record<string,unknown>)=>void;onAction:(b:Record<string,unknown>)=>Promise<boolean>}){
  const [name,setName]=useState(p.name),[rules,setRules]=useState(p.limitsEnabled!==false);const [stake,setStake]=useState(p.stakeBps/100),[exposure,setExposure]=useState(p.exposureBps/100),[day,setDay]=useState(p.dayBps/100),[drawdown,setDrawdown]=useState(p.drawdownBps/100);
  return <form className="panel limits" onSubmit={e=>{e.preventDefault();onSave({stakeBps:Math.round(stake*100),exposureBps:Math.round(exposure*100),dayBps:Math.round(day*100),drawdownBps:Math.round(drawdown*100)});}}><div className="panel-heading"><h3>Il tuo portafoglio</h3><Shield size={18}/></div><div className="portfolio-admin"><label>Nome<input maxLength={40} value={name} onChange={e=>setName(e.target.value)}/></label><button type="button" className="secondary small-button" disabled={busy||!name.trim()||name===p.name} onClick={()=>onAction({action:'rename',name})}>Rinomina</button><button type="button" className="text-button danger" disabled={busy} onClick={()=>{if(window.confirm('Eliminare questo portafoglio? Possibile solo se è vuoto.'))onAction({action:'delete'});}}>Elimina</button></div><label className="rules-toggle"><input type="checkbox" checked={rules} disabled={busy} onChange={e=>{setRules(e.target.checked);onAction({action:'limits',enabled:e.target.checked});}}/><span><strong>Regole di gestione del capitale</strong><small>{rules?'Attive: QUORUM blocca le puntate oltre i limiti qui sotto.':'Disattivate: puoi puntare liberamente. I limiti restano solo come riferimento.'}</small></span></label><p className="muted">Avanzato: i limiti uno per uno. Di solito basta scegliere il profilo o la percentuale qui sopra, che li calcola da soli.</p>{[{label:'Singola operazione',value:stake,set:setStake,max:20},{label:'Esposizione aperta',value:exposure,set:setExposure,max:60},{label:'Perdita giornaliera',value:day,set:setDay,max:60},{label:'Stop drawdown',value:drawdown,set:setDrawdown,max:90}].map(s=><label className="limit-field" key={s.label}><span>{s.label}</span><div><input type="number" required min="0.01" max={s.max} step="0.01" value={s.value} onChange={e=>s.set(Number(e.target.value))}/><b>%</b></div></label>)}<div className="budget-note"><span>Budget giornaliero residuo*</span><strong>{money(Math.max(0,Math.floor(m.dayStartCents*p.dayBps/10000)-m.dayLossCents-m.openCents))}</strong></div><p className="tiny">*Perdita netta di oggi più tutte le puntate ancora aperte. Il giorno segue l’ora di Roma. Il drawdown si misura dal massimo capitale raggiunto.</p><button className="primary" disabled={busy}>Salva limiti<Check size={16}/></button></form>;
}

// Every possible outcome of the user's system, in plain words: which matches are right, which small tickets win,
// how much comes back. Shown inline (key cases) and in the ⓘ window (all cases).
function systemScenarios(s:Selection[],active:{k:number;unitCents:number}[]){
  const n=s.length,groups=active.map(c=>({...c,combos:combinations(n,c.k)})),cost=groups.reduce((x,g)=>x+g.combos.length*g.unitCents,0);
  const out:{mask:number;right:number[];wrong:number[];wins:{c:number[];cents:number}[];back:number;net:number;p:number}[]=[];
  for(let mask=(1<<n)-1;mask>=0;mask--){
    const right=[...Array(n).keys()].filter(i=>mask&(1<<i)),wrong=[...Array(n).keys()].filter(i=>!(mask&(1<<i)));
    const wins=groups.flatMap(g=>g.combos.filter(c=>c.every(i=>mask&(1<<i))).map(c=>({c,cents:Math.round(g.unitCents*c.reduce((o,i)=>o*s[i].odds,1))})));
    const back=wins.reduce((x,w)=>x+w.cents,0),p=s.reduce((v,x,i)=>v*((mask&(1<<i))?x.p:1-x.p),1);
    out.push({mask,right,wrong,wins,back,net:back-cost,p});
  }
  return {cost,list:out.sort((a,b)=>b.right.length-a.right.length||b.net-a.net)};
}
function ScenarioCard({x,s}:{x:ReturnType<typeof systemScenarios>['list'][number];s:Selection[]}){
  const nm=(i:number)=>s[i].fixture.split(' – ')[0];
  return <div className={'scn '+(x.net>0?'gain':x.back>0?'part':'loss')}>
    <div className="scn-head"><span>{x.right.length===s.length?'Indovini tutte':x.right.length===0?'Sbagli tutte':'Indovini '+x.right.length+' su '+s.length}</span><b>{x.net>=0?'+':'−'}{money(Math.abs(x.net))}</b></div>
    <div className="scn-picks">{x.right.map(i=><span key={i} className="ok">✓ {nm(i)}</span>)}{x.wrong.map(i=><span key={i} className="ko">✗ {nm(i)}</span>)}</div>
    <p>{x.wins.length?<>Vincono {x.wins.length===1?'questa schedina':'queste '+x.wins.length+' schedine'}: {x.wins.map((w,j)=><span key={j} className="scn-win">{w.c.map(nm).join(' + ')} <i>{money(w.cents)}</i></span>)}</>:'Nessuna schedina vince: ogni schedina piccola contiene almeno una partita sbagliata.'}</p>
    <p className="scn-sum">Incassi <b>{money(x.back)}</b> · hai speso {money(x.back-x.net)} · {x.net>0?'sei in guadagno':x.back>0?'recuperi una parte':'perdi tutto'} · probabilità {percent(x.p,x.p<0.1?1:0)}</p>
  </div>;
}
function Laboratory({selections:s,setSelections,onBrowse,onExample,onRecordSystem,notify}:{selections:Selection[];setSelections:(s:Selection[])=>void;onBrowse:()=>void;onExample:()=>void;notify?:(m:string)=>void;onRecordSystem?:(legs:any[],classes:{k:number;unitCents:number}[],shared:boolean)=>Promise<boolean>}){
  const [picker,setPicker]=useState(false);
  const addPick=(x:Selection)=>{if(s.some(v=>v.fixtureId===x.fixtureId)){notify?.('Questa partita è già nel sistema: un solo esito per partita.');return;}if(s.length>=8){notify?.('Massimo 8 partite nel Laboratorio.');return;}setSelections([...s,x]);notify?.(x.fixture+' · '+x.label+' aggiunta.');};
  const n=s.length;
  // Classes like the bookmaker's slip: Singole, Doppie, Triple… each with its own stake per combination.
  const [cls,setCls]=useState<Record<number,{on:boolean;unit:string}>>(()=>{try{const v=JSON.parse(localStorage.getItem('quorum-lab-classes')||'null');localStorage.removeItem('quorum-lab-classes');if(Array.isArray(v)&&v.length)return Object.fromEntries(v.map((c:any)=>[c.k,{on:true,unit:(c.unitCents/100).toFixed(2)}]));}catch{}return {};});
  const [amount,setAmount]=useState('3'),[amode,setAmode]=useState<'divide'|'each'|'manual'>(()=>Object.keys(cls).length?'manual':'divide');
  const row=(k:number)=>cls[k]??{on:k===n,unit:'2'};
  const setRow=(k:number,v:Partial<{on:boolean;unit:string}>)=>setCls(c=>({...c,[k]:{...row(k),...v}}));
  const ks=Array.from({length:n},(_,i)=>i+1),nCk=(k:number)=>combinations(n,k).length;
  const active=ks.filter(k=>row(k).on&&Number(row(k).unit)>0).map(k=>({k,unitCents:Math.round(Number(row(k).unit)*100)}));
  const result=useMemo(()=>{try{return n&&active.length?evaluateClasses(s,active):null;}catch{return null;}},[s,JSON.stringify(active)]);
  const preset=(kind:'multi'|'full')=>setCls(Object.fromEntries(ks.map(k=>[k,{on:kind==='full'||k===n,unit:row(k).unit}])));
  const assignAll=()=>{const v=Number(amount.replace(',','.'));if(v>0)setCls(Object.fromEntries(ks.map(k=>[k,{...row(k),unit:v.toFixed(2)}])));};
  const divide=()=>{const v=Number(amount.replace(',','.')),on=ks.filter(k=>row(k).on),tot=on.reduce((x,k)=>x+nCk(k),0);if(v>0&&tot)setCls(Object.fromEntries(ks.map(k=>[k,{...row(k),unit:(Math.floor(v*100/tot)/100).toFixed(2)}])));};
  // The amount updates the stakes as you type: split across all the chosen combinations, or the same on each one.
  const onKey=ks.map(k=>row(k).on?'1':'0').join('');
  useEffect(()=>{if(amode==='divide')divide();else if(amode==='each')assignAll();},[amount,amode,onKey,n]);
  const short=(x:Selection)=>x.fixture.split(' – ')[0];
  const [info,setInfo]=useState(false);
  const scen=useMemo(()=>n&&n<=8&&active.length?systemScenarios(s,active):null,[s,JSON.stringify(active)]);
  const label=(k:number)=>k===n&&n>1?'Multipla ('+className(k,n).toLowerCase()+')':className(k,n);
  const sysName=active.length===1&&active[0].k===n?(n===1?'Singola':'Multipla'):'Sistema '+n+' eventi · '+active.map(c=>className(c.k,n)).join(' + ');
  const [share,setShare]=useState(()=>{try{return localStorage.getItem('quorum-share')==='1';}catch{return false;}}),[saving,setSaving]=useState(false),[saveMsg,setSaveMsg]=useState('');
  async function saveSystem(){
    if(!onRecordSystem||!result)return;setSaving(true);setSaveMsg('');
    try{
      let legs=s.map(x=>({...x}));
      if(legs.some(x=>!x.kickoff||!x.competition)){const d:any=await fetch('/api/scanner?view=predictions',{cache:'no-store'}).then(r=>r.json()).catch(()=>({matches:[]}));for(const l of legs){const m=(d.matches||[]).find((y:any)=>y.fixture_id===l.fixtureId);if(m){l.kickoff=l.kickoff||m.kickoff;l.competition=l.competition||m.competition;}}}
      if(legs.some(x=>!/^sm-\d+$/.test(x.fixtureId)||!x.kickoff)){setSaveMsg('Alcune partite non hanno data o identificativo: aggiungile da Pronostici, Costruisci o Centro partita.');return;}
      const ok=await onRecordSystem(legs.map(l=>({fixtureId:l.fixtureId,fixture:l.fixture,competition:l.competition||'',kickoff:l.kickoff!,market:l.market,label:l.label,p:l.p,odds:l.odds})),active,share);
      if(ok)setSaveMsg(share?'Sistema registrato e condiviso: lo trovi in Risultati.':'Sistema registrato: lo trovi in Risultati, si regola da solo.');
    }finally{setSaving(false);}
  }
  return <><div className="page-heading"><div><p className="eyebrow">MATEMATICA, SENZA SCORCIATOIE</p><h1>Metti le idee alla prova<span>.</span></h1><p>Confronta singole, multiple e sistemi. Guarda anche ciò che puoi perdere.</p></div><button className="secondary" onClick={onExample}><FlaskConical size={16}/>Usa una schedina QUORUM</button></div><div className="callout lab-callout"><Info size={20}/><p>Calcolo teorico: le partite sono considerate <strong>indipendenti</strong> e le probabilità sono stime non validate. Più combinazioni aumentano la copertura e il costo; non rendono positivo un valore atteso negativo.</p></div><div className="lab-columns"><section className="panel"><div className="panel-heading"><h3>Le ipotesi da confrontare</h3><div className="lab-head-actions"><Tag tone="neutral">{s.length} / 8 PARTITE</Tag>{s.length>0&&<button className="text-button danger" onClick={()=>setSelections([])}><X size={15}/>Svuota</button>}</div></div>{!s.length?<><Empty compact icon={<FlaskConical/>} title="Un’idea ha bisogno di numeri." text="Carica una schedina QUORUM o aggiungi un esito dal Centro partita. Il laboratorio non muove denaro." action={<div className="lab-empty-actions"><button className="primary" onClick={onExample}>Usa una schedina QUORUM<ArrowRight size={16}/></button><button className="secondary" onClick={()=>setPicker(true)}><Plus size={16}/>Scegli le partite tu</button></div>}/>{picker&&<LabPicker onAdd={addPick} taken={[]}/>}</>:<>{s.map((x,i)=><div className="system-pick" key={x.fixtureId}><span className="pick-index">0{i+1}</span><div><strong>{x.fixture}</strong><p>{x.label} · Stima {percent(x.p)}</p></div><label>Quota<input aria-label={'Quota '+x.fixture} type="number" min="1.01" max="1000" step="0.01" value={x.odds} onChange={e=>setSelections(s.map((v,j)=>j===i?{...v,odds:Number(e.target.value)}:v))}/></label><button className="icon-button" onClick={()=>setSelections(s.filter((_,j)=>i!==j))} aria-label={'Rimuovi '+x.fixture}><X size={17}/></button></div>)}<button className="text-button add-event" onClick={()=>setPicker(!picker)}><Plus size={16}/>{picker?'Chiudi la scelta delle partite':'Aggiungi una partita: qualsiasi campionato e mercato'}</button>{picker&&<LabPicker onAdd={addPick} taken={s.map(x=>x.fixtureId)}/>}</>}{n>0&&<div className="sys-classes">
    <div className="sys-presets"><button className={'filters-like'+(active.length===1&&active[0].k===n?' on':'')} onClick={()=>preset('multi')}>Multipla</button><button className={'filters-like'+(active.length===n&&n>1?' on':'')} onClick={()=>preset('full')}>Sistema completo ({ks.reduce((x,k)=>x+nCk(k),0)} combinazioni)</button></div>
    <div className="sys-amount"><span>Importo</span><input inputMode="decimal" value={amount} onChange={e=>{const v=e.target.value.replace(/[^0-9.,]/g,'');setAmount(v);if(amode==='manual')setAmode('divide');}} aria-label="Importo totale della schedina"/><span>€</span><button className={amode==='divide'?'secondary on':'secondary'} onClick={()=>setAmode('divide')} title="L’importo è il totale: si divide tra tutte le combinazioni scelte">Totale da dividere</button><button className={amode==='each'?'secondary on':'secondary'} onClick={()=>setAmode('each')} title="L’importo è la puntata di ogni combinazione">Per ogni combinazione</button></div>
    <p className="small-note sys-amount-note">{amode==='manual'?'Puntate scritte a mano per ogni classe. Scrivi un importo qui sopra per ricalcolarle tutte.':amode==='divide'?'Scrivi quanto vuoi spendere in tutto: QUORUM lo divide tra le combinazioni e aggiorna subito vincite e probabilità.':'Ogni combinazione gioca questo importo: il totale è l’importo × il numero di combinazioni.'}</p>
    {ks.slice().reverse().map(k=>{const r=row(k);let mn=0,mx=0;try{if(r.on&&Number(r.unit)>0){const e=evaluateClasses(s,[{k,unitCents:Math.round(Number(r.unit)*100)}]);mn=e.minWinCents;mx=e.maxReturnCents;}}catch{}return <div key={k} className={'sys-class'+(r.on?' on':'')}>
      <label className="sys-check"><input type="checkbox" checked={r.on} onChange={e=>setRow(k,{on:e.target.checked})}/><b>{label(k)}</b><small>{nCk(k)}x</small></label>
      <div className="sys-stake"><button onClick={()=>{setAmode('manual');setRow(k,{unit:Math.max(0.05,Number(r.unit)-0.05).toFixed(2)});}}>−</button><input inputMode="decimal" value={r.unit} onChange={e=>{setAmode('manual');setRow(k,{unit:e.target.value.replace(',','.')});}} aria-label={'Puntata per combinazione '+label(k)}/><button onClick={()=>{setAmode('manual');setRow(k,{unit:(Number(r.unit)+0.05).toFixed(2)});}}>+</button></div>
      {r.on&&<div className="sys-class-win"><span>Vincita min <b>{money(mn)}</b></span><span>Vincita max <b>{money(mx)}</b></span></div>}
      <details className="sys-combos"><summary>Quali sono le {nCk(k)} {nCk(k)===1?'combinazione':'combinazioni'}</summary><ul>{combinations(n,k).map(c=>{const q=c.reduce((o,i)=>o*s[i].odds,1);return <li key={c.join()}><span>{c.map(i=>short(s[i])).join(' + ')}</span><i>quota {q.toFixed(2)}</i>{r.on&&Number(r.unit)>0&&<b>vince {money(Math.round(Number(r.unit)*100*q))}</b>}</li>;})}</ul></details>
    </div>;})}
    <details className="sys-legend" open={n>1&&n<=4}><summary>Come funziona il sistema, spiegato semplice</summary>
      <p>Hai <b>{n} partite</b>: {s.map((x,i)=><span key={x.fixtureId}>{i>0?(i===n-1?' e ':', '):''}<b>{short(x)}</b> ({x.label})</span>)}.</p>
      <p>Un sistema è un <b>pacchetto di tante schedine piccole</b> fatte con le stesse partite. Ogni schedina piccola è una <b>combinazione</b>: vince solo se indovini <b>tutte</b> le partite che contiene, e ha la sua puntata.</p>
      <ul>
        <li><b>Singole</b>: ogni partita da sola → {nCk(1)} schedine.</li>
        {n>=2&&<li><b>Doppie</b>: le partite a coppie → {nCk(2)} schedine{n===3?' ('+combinations(3,2).map(c=>c.map(i=>short(s[i])).join('+')).join(', ')+')':''}.</li>}
        {n>=3&&n!==3&&<li><b>Triple</b>: a gruppi di tre → {nCk(3)} schedine.</li>}
        {n>=2&&<li><b>Multipla</b>: tutte insieme → 1 schedina.</li>}
      </ul>
      <p>Il numero accanto (“3x”, “1x”) è <b>quante schedine</b> ci sono in quella classe. Con {n} partite i gruppi possibili sono in tutto <b>{Math.pow(2,n)-1}</b>{n===3?' = 3 singole + 3 doppie + 1 tripla. Non 10: con 3 partite non esistono altri modi di raggrupparle':''}. Ogni partita in più quasi raddoppia le combinazioni (4 partite = 15, 5 = 31).</p>
      <p><b>Cosa cambia spuntando più classi:</b> solo la Multipla = paghi poco e vinci tanto, ma basta un errore per perdere tutto. Aggiungendo Doppie e Singole paghi di più (ogni schedina piccola ha la sua puntata), ma <b>resti in gioco anche se ne sbagli qualcuna</b>: le combinazioni senza la partita sbagliata vincono lo stesso. La tabella “Se ne vincono” qui a destra ti dice, per ogni numero di partite indovinate, quanto incassi e se sei in profitto.</p>
    </details>
    <p className="tiny">Puntata per singola combinazione, come sulla schedina di Lottomatica / Planetwin365. Un esito per partita.</p>
  </div>}</section><section className="panel system-result"><div className="panel-heading"><h3>Il risultato del confronto <button className="info-dot" onClick={()=>setInfo(true)} aria-label="Cosa succede con la tua schedina" title="Cosa succede con la tua schedina">i</button></h3><Tag tone="amber">{sysName}</Tag></div>{result?<>
    <div className="sys-summary"><div><span>Combinazioni</span><b>{result.tickets}</b></div><div><span>Importo sistema</span><b>{money(result.costCents)}</b></div><div><span>Vincita min</span><b className="positive">{money(result.minWinCents)}</b></div><div><span>Vincita max</span><b className="positive">{money(result.maxReturnCents)}</b></div></div>
    <div className={'sys-breakeven'+(result.breakEven===null?' no':'')}>{result.breakEven===null?'Con queste puntate non vai mai in profitto: alza le classi più alte.':result.breakEven===n?'Vai in profitto solo se vincono tutte e '+n+'.':<>Vai in profitto se ne vincono <b>almeno {result.breakEven} su {n}</b>: puoi sbagliarne {n-result.breakEven}.</>}</div>
    <span className="muted">Probabilità di chiudere in profitto</span><div className="big-probability">{percent(result.pProfit)}</div><div className="prob-track"><span style={{width:result.pProfit*100+'%'}}/></div>
    <div className="sys-table"><div className="sys-tr head"><span>Se ne vincono</span><span>Incasso</span><span>Netto</span><span>Probabilità</span></div>{result.byWinners.slice().reverse().map(b=>{const netMin=b.minReturnCents-result.costCents,netMax=b.maxReturnCents-result.costCents;return <div key={b.winners} className={'sys-tr'+(netMin>0?' gain':netMax<=0?' loss':' mixed')}><span>{b.winners} su {n}</span><span>{b.minReturnCents===b.maxReturnCents?money(b.maxReturnCents):money(b.minReturnCents)+' – '+money(b.maxReturnCents)}</span><span>{netMin===netMax?(netMax>=0?'+':'')+money(netMax):(netMin>=0?'+':'')+money(netMin)+' / '+(netMax>=0?'+':'')+money(netMax)}</span><span>{percent(b.p,0)}</span></div>;})}</div>
    {scen&&<div className="scn-inline"><div className="scn-title"><b>Cosa succede con la tua schedina</b><button className="info-dot" onClick={()=>setInfo(true)} aria-label="Tutti i casi">i</button></div>
      <p className="tiny">Hai {result.tickets===1?'1 schedina':result.tickets+' schedine piccole'} per {money(result.costCents)} in tutto. Ecco i casi principali; tocca <b>i</b> per vederli tutti.</p>
      {[scen.list[0],scen.list.find(x=>x.right.length===n-1&&n>1),scen.list.filter(x=>x.right.length===n-1).slice(-1)[0],scen.list.find(x=>x.right.length===1&&n>2),scen.list[scen.list.length-1]].filter((x,i,a)=>x&&a.indexOf(x)===i).map(x=><ScenarioCard key={x!.mask} x={x!} s={s}/>)}
    </div>}
    <div className="calc-row"><span>Almeno una combinazione vincente</span><strong>{percent(result.pWin)}</strong></div><div className="calc-row"><span>Valore atteso netto</span><strong className={result.expectedCents<0?'negative':'positive'}>{money(result.expectedCents)}</strong></div>
    <p className="tiny">Incasso = quanto ti paga il bookmaker (puntata compresa). Quando ne vincono lo stesso numero l’incasso cambia in base a quali vincono: per questo c’è un intervallo. Probabilità stimate da QUORUM, partite considerate indipendenti.</p>
    {onRecordSystem&&<div className="lab-save"><label className="share-toggle"><input type="checkbox" checked={share} onChange={e=>{setShare(e.target.checked);try{localStorage.setItem('quorum-share',e.target.checked?'1':'0');}catch{}}}/><span>Condividi con gli altri utenti di QUORUM</span></label><button className="lime-button" disabled={saving||result.costCents<100} onClick={saveSystem}><Check size={16}/>{saving?'Registro…':'Registra · '+money(result.costCents)}</button>{result.costCents<200&&<small className="tiny">Importo minimo: 2 €.</small>}{saveMsg&&<p className="connection-success">{saveMsg}</p>}</div>}
  </>:<Empty compact icon={<BarChart3/>} title="Il confronto apparirà qui." text="Aggiungi almeno una partita e scegli una classe con la puntata."/>}</section></div>
  {info&&scen&&result&&<Dialog title="Cosa succede con la tua schedina" onClose={()=>setInfo(false)} wide><div className="scn-dialog">
    <h3>Come funziona, in 3 righe</h3>
    <ol><li>Il sistema è un <b>pacchetto di schedine piccole</b> fatte con le tue {n} partite: qui sono <b>{result.tickets}</b>, per {money(result.costCents)} in tutto.</li><li>Ogni schedina piccola <b>vince solo se indovini tutte le partite che contiene</b>, e paga la sua puntata × le sue quote.</li><li>Alla fine incassi la <b>somma</b> delle schedine piccole che hanno vinto. Se è più di quanto hai speso, sei in guadagno.</li></ol>
    <h3>Le tue {result.tickets} schedine piccole</h3>
    <div className="scn-tickets">{active.map(c=><div key={c.k}><b>{label(c.k)} · {nCk(c.k)}x · {money(c.unitCents)} ciascuna</b><ul>{combinations(n,c.k).map(cb=><li key={cb.join()}>{cb.map(i=>short(s[i])).join(' + ')} <i>quota {cb.reduce((o,i)=>o*s[i].odds,1).toFixed(2)} → vince {money(Math.round(c.unitCents*cb.reduce((o,i)=>o*s[i].odds,1)))}</i></li>)}</ul></div>)}</div>
    <h3>Tutti i casi possibili ({scen.list.length})</h3>
    <p className="tiny">Verde = guadagni · giallo = recuperi una parte · rosso = perdi tutto. La probabilità è la stima QUORUM.</p>
    <div className="scn-grid">{scen.list.map(x=><ScenarioCard key={x.mask} x={x} s={s}/>)}</div>
  </div></Dialog>}</>;
}

function Method({portfolio:p}:{portfolio:Portfolio}){
  const [losses,setLosses]=useState(10),[risk,setRisk]=useState(p.stakeBps/100);
  const remaining=p.initialCents*Math.pow(1-risk/100,losses);
  return <><div className="page-heading"><div><p className="eyebrow">CAPIRE PRIMA DI DECIDERE</p><h1>Il metodo fa la differenza<span>.</span></h1><p>Tre domande: quanto è probabile, quanto costa, quanto puoi perdere?</p></div><Tag tone="neutral">EDUCAZIONE + TRASPARENZA</Tag></div><div className="method-cards">{[{n:'01',icon:BarChart3,title:'Misura la probabilità',text:'Il modello distribuisce le possibilità tra tutti gli esiti. Anche il risultato più probabile può avere poche chance di verificarsi.'},{n:'02',icon:Target,title:'Confrontala con la quota',text:'Una probabilità alta non basta. Con p = 60% e quota 1,50, il valore atteso è −10% della puntata.'},{n:'03',icon:Shield,title:'Proteggi il capitale',text:'Le soglie bloccano nuove registrazioni oltre i limiti. Non aumentiamo la puntata automaticamente dopo una perdita.'}].map(x=><section className="panel method-card" key={x.n}><div><span>{x.n}</span><x.icon size={24}/></div><h3>{x.title}</h3><p>{x.text}</p></section>)}</div><div className="dashboard-columns"><section className="panel lessons"><h3>Le cose da sapere, senza giri di parole.</h3>{[['Una vincita non è sempre un profitto','In un sistema paghi tutte le combinazioni. Se ne vince una, l’incasso può restare inferiore alla spesa totale. Per questo mostriamo entrambe le probabilità.'],['Il risultato esatto non è una certezza nascosta','Il punteggio con la probabilità più alta non ha necessariamente più del 10–15% di possibilità. Coprire più punteggi aumenta anche il costo. Le percentuali cambiano con i parametri e vanno validate.'],['Il money management non crea un vantaggio','Limitare la puntata contiene l’esposizione. Non trasforma un modello impreciso o quote sfavorevoli in un’attività redditizia.'],['Come dovremo validare il modello','Prima test cronologici su dati mai usati nell’addestramento, poi registrazioni prima delle partite reali. Servono calibrazione, Brier score, confronto con il mercato, quote effettivamente disponibili e costi. I test demo e gli esiti inseriti a mano non provano un rendimento reale.'],['Che cosa è attivo in questa beta','Sono attivi calcoli Poisson, risultati esatti, scenari di corner e cartellini con distribuzione binomiale negativa, confronto dei sistemi e portafoglio virtuale. L’analista AI è disponibile su richiesta dopo il collegamento della chiave. Non sono ancora attivi modello addestrato, xG, quote automatiche, rendicontazione verificata dal fornitore o abbonamenti.']].map(([title,text])=><details key={title}><summary>{title}<Plus size={16}/></summary><p>{text}</p></details>)}</section><section className="panel stress-test"><Tag tone="amber">STRESS TEST</Tag><h3>E se perdessi {losses} volte di fila?</h3><p>Esperimento ipotetico: ogni nuova puntata è la stessa percentuale del capitale rimasto.</p><label>Sconfitte consecutive<strong>{losses}</strong><input type="range" min="1" max="50" value={losses} onChange={e=>setLosses(Number(e.target.value))}/></label><label>Rischio per operazione (%)<input type="number" step="0.1" min="0.1" max="20" value={risk} onChange={e=>setRisk(Math.min(20,Math.max(0,Number(e.target.value))))}/></label><div className="stress-result"><span>Capitale iniziale {money(p.initialCents)}</span><strong>{money(remaining)}</strong><small>Capitale residuo · perdita {percent(1-remaining/p.initialCents)}</small></div><p className="tiny">Esempio matematico. Non stima la probabilità della sequenza e non applica gli stop del portafoglio.</p></section></div></>;
}
